// The corpus: how the same code looks in every stack format the SDK sees.
// testdata/mono/* are real outputs of Unity's Mono (2022.3.62f3
// MonoBleedingEdge) and of UnityEngine.StackTraceUtility, generated by a
// small program with the shape of OZX's code (paths anonymised); the IL2CPP
// and Unity-console variants below follow the formats of the same versions.

const busPrefix = "[GameEventBus] Error handling event RoomEnteredEvent: "

// The handler of RoomEnteredEvent in EnemySpawner (a lambda) dereferences null.
// Same code, four stack formats; the line numbers differ on purpose.
const (
	spawnerNREMono = `System.NullReferenceException: Object reference not set to an instance of an object
  at Ozx.Rooms.EnemySpawner.SpawnWave (System.Int32 roomId) [0x0000a] in /Users/dev/ozx/Assets/Scripts/Rooms/EnemySpawner.cs:88
  at Ozx.Rooms.EnemySpawner.<Register>b__2_0 (Ozx.Core.RoomEnteredEvent e) [0x00008] in /Users/dev/ozx/Assets/Scripts/Rooms/EnemySpawner.cs:82
  at Ozx.Core.GameEventBus.Publish[T] (T evt) [0x00040] in /Users/dev/ozx/Assets/Scripts/Core/GameEventBus.cs:48 `

	// IL2CPP release build without line number information.
	spawnerNREIL2CPP = `System.NullReferenceException: Object reference not set to an instance of an object.
  at Ozx.Rooms.EnemySpawner.SpawnWave (System.Int32 roomId) [0x00000] in <00000000000000000000000000000000>:0
  at Ozx.Rooms.EnemySpawner.<Register>b__2_0 (Ozx.Core.RoomEnteredEvent e) [0x00000] in <00000000000000000000000000000000>:0
  at Ozx.Core.GameEventBus.Publish[T] (T evt) [0x00000] in <00000000000000000000000000000000>:0 `

	// IL2CPP with Il2CppStacktraceInformation.MethodFileLineMapping (OZX-1277),
	// built from a later version: every line number moved.
	spawnerNREIL2CPPLines = `System.NullReferenceException: Object reference not set to an instance of an object.
  at Ozx.Rooms.EnemySpawner.SpawnWave (System.Int32 roomId) [0x00000] in /Users/builder/ozx/Assets/Scripts/Rooms/EnemySpawner.cs:97
  at Ozx.Rooms.EnemySpawner.<Register>b__2_0 (Ozx.Core.RoomEnteredEvent e) [0x00000] in /Users/builder/ozx/Assets/Scripts/Rooms/EnemySpawner.cs:91
  at Ozx.Core.GameEventBus.Publish[T] (T evt) [0x00000] in /Users/builder/ozx/Assets/Scripts/Core/GameEventBus.cs:51 `

	// .NET (e.g. a server-side tool sharing the code).
	spawnerNREDotNet = `System.NullReferenceException: Object reference not set to an instance of an object.
   at Ozx.Rooms.EnemySpawner.SpawnWave(Int32 roomId) in C:\ozx\Assets\Scripts\Rooms\EnemySpawner.cs:line 88
   at Ozx.Rooms.EnemySpawner.<Register>b__2_0(RoomEnteredEvent e) in C:\ozx\Assets\Scripts\Rooms\EnemySpawner.cs:line 82
   at Ozx.Core.GameEventBus.Publish[T](T evt) in C:\ozx\Assets\Scripts\Core\GameEventBus.cs:line 48`
)

// The other handler of the same event: RoomLoader throws for an unknown room.
// The roomId is in the message.
func roomLoaderIOE(roomID string, il2cpp bool) string {
	loc := func(file string, line string) string {
		if il2cpp {
			return "[0x00000] in <00000000000000000000000000000000>:0 "
		}
		return "[0x0001b] in /Users/dev/ozx/Assets/Scripts/" + file + ":" + line + " "
	}
	return "System.InvalidOperationException: Room template not found for roomId=" + roomID + " (room_" + roomID + ")\n" +
		"  at Ozx.Rooms.RoomLoader.LoadTemplate (System.Int32 roomId) " + loc("Rooms/RoomLoader.cs", "71") + "\n" +
		"  at Ozx.Rooms.RoomLoader.OnRoomEntered (Ozx.Core.RoomEnteredEvent e) " + loc("Rooms/RoomLoader.cs", "64") + "\n" +
		"  at Ozx.Core.GameEventBus.Publish[T] (T evt) " + loc("Core/GameEventBus.cs", "48")
}

// Unity's stack of the Debug.LogError call in GameEventBus.Publish.
const (
	busLogErrorStackEditor = "UnityEngine.Debug:LogError (object)\n" +
		"Ozx.Core.GameEventBus:Publish<Ozx.Core.RoomEnteredEvent> (Ozx.Core.RoomEnteredEvent) (at Assets/Scripts/Core/GameEventBus.cs:52)\n" +
		"Ozx.Rooms.RoomManager:EnterRoom (int) (at Assets/Scripts/Rooms/RoomManager.cs:140)\n"
	// IL2CPP release: Unity omits its own frame and has no locations
	// (as seen in a logcat of the APM test app: "ApmTestDriver:Update()").
	busLogErrorStackIL2CPP = "Ozx.Core.GameEventBus:Publish(RoomEnteredEvent)\nOzx.Rooms.RoomManager:EnterRoom(Int32)\n"
	// IL2CPP with line numbers.
	busLogErrorStackIL2CPPLines = "Ozx.Core.GameEventBus:Publish(RoomEnteredEvent) (at /Users/builder/ozx/Assets/Scripts/Core/GameEventBus.cs:55)\n" +
		"Ozx.Rooms.RoomManager:EnterRoom(Int32) (at /Users/builder/ozx/Assets/Scripts/Rooms/RoomManager.cs:141)\n"
)

func readFixture(t *testing.T, name string) string {
	t.Helper()
	b, err := os.ReadFile("testdata/mono/" + name)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// wrapped is what the SDK (APM-4) sends for a bus error: the message (first
// 500 characters, as before), Unity's stack, and the embedded exception.
func wrapped(ex, stack string) Input {
	msg := busPrefix + ex
	if len(msg) > 500 {
		msg = msg[:497] + "..."
	}
	return Input{LogType: LogTypeError, Message: msg, Stack: stack, Embedded: ex}
}

// legacy is what an SDK before APM-4 sent for the same error: no log type, no
// embedded exception, the message cut to 500 characters.
func legacy(ex, stack string) Input {
	in := wrapped(ex, stack)
	in.LogType, in.Embedded = "", ""
	return in
}

func mustFingerprint(t *testing.T, in Input) Result {
	t.Helper()
	r := Analyze(in)
	if len(r.Fingerprint) != 16 || strings.Trim(r.Fingerprint, "0123456789abcdef") != "" {
		t.Fatalf("bad fingerprint %q", r.Fingerprint)
	}
	if r.Version != Version {
		t.Fatalf("version %d", r.Version)
	}
	return r
}
